-- GENERATED by `wfj generate` from data/gossip/gossip-7e.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["7e046fb716e40080"] = { "Salute, {class}.\n\nQuelle ⟦Sentinels=Sentinelle⟧ laggiù mi hanno permesso di condividere il loro accampamento, purché prometta che non ne seguiranno guai: di certo capirai il bisogno di diplomazia qui, vero?\n\nSono qui per indagare sui turbamenti della terra e, poiché questo aiuta anche la loro causa, hanno convenuto che la mia presenza potrebbe solo giovare alla fragile alleanza fra tutte le razze di Azeroth. Se vuoi aiutarmi, il tuo aiuto sarà gradito; ma in ogni caso, cerca di non causare guai.", "." },
  ["7e047ac5aa934712"] = { "La ⟦Coldtooth Mine=Miniera di Dentefreddo⟧ è in mano ai coboldi.", "." },
  ["7e0a567910e0075c"] = { "Ah ah, <ragazzo/ragazza>! L'⟦Alliance=Alleanza⟧ ha raccolto tutto quello che ci serve per far cominciare 'sta guerra! Magari l'⟦Horde=Orda⟧ ci raggiungerà presto?", "." },
  ["7e0c56ff5320ed8e"] = { "Non posso insegnare ciò che non so! Se solo ci fosse qualcun altro che ne sa più di me... aspetta, c'è! Va' da Buzzek Bracketswing a ⟦Gadgetzan=Meccania⟧!", "." },
  ["7e0cb2712357976c"] = { "Cairne ci ha condotti in una terra ricca di possibilità per il futuro. Siamo stati fortunati, e così a nostra volta trasmettiamo la nostra buona sorte agli altri. È per questo che ho iniziato a insegnare, {name}.", "." },
  ["7e0e172e4f3ad944"] = { "In epoche passate, Eldre'Thalas era un nesso di potere magico, e chi abitava le sue sale consacrate esercitava un potere immenso. Una di questi elfi della notte era Millicent Serene, una naturalista che infondeva il potere stesso della natura nei potenti manufatti che forgiava.\n\nIl Fruit of Fertility fu il suo capolavoro... usò un pozzo lunare preparato apposta per far crescere una vite esotica e rigogliosa, permeata da un'aura di protezione e crescita. Tutta Eldre'Thalas prosperò grazie alla sua esistenza.", "." },
  ["7e17081a26ff0142"] = { "Ora ripuliamo il resto della spazzatura, uomini!", "." },
  ["7e2143ae2154063c"] = { "Questo prometto... Questo giuro...", "." },
  ["7e21ffca8cbde3de"] = { "Hai urtato l'ammasso e le spore ti hanno fatto ammalare!", "." },
  ["7e2227aa1d9fe634"] = { "Io... non riesco nemmeno a immaginarlo, {name}. So solo che non permetterò che accada. Verrà distrutto: se non per la nostra sicurezza dalla contaminazione demoniaca, almeno in memoria di Millicent Serene... Milli...\n\nEd è qui, amico mio, che spero entrerai in gioco tu.", "." },
  ["7e338222cd594944"] = { "I piatti che prepara Alegorn sono da leccarsi i baffi. È sempre indaffarato a preparare nuove prelibatezze nella Craftsman's Terrace. Assaggia la sua ricetta Cenarion Green, se gliene è rimasta.\n\nOra, se non ti dispiace, devo indagare su questa serie di cervi scomparsi.", "." },
  ["7e361bec32b4cf40"] = { "Di sicuro troverò un uso per questa miscela...", "." },
  ["7e37548455e297c1"] = { "So molte cose: ascolta e impara, {race}.", "." },
  ["7e37a815658642ee"] = { "Chi controlla il Dun Baldar North Bunker?", "." },
  ["7e38af6f71a16552"] = { "Sono a caccia di tesori, in cerca di potenti manufatti. Dammeli e non ti sarà fatto alcun male.", "." },
  ["7e3fe2ba4487d1b0"] = { "%s erutta una disgustosa Fanghiglia di Bile!", "." },
  ["7e4522c484f31c81"] = { "Ho sentito che, dopo lo spettacolo pirotecnico, porteranno i calici ai tavoli. Faremo dei bei brindisi!", "." },
  ["7e46bb6badc55b59"] = { "%s esulta!", "." },
  ["7e4716e4447f5e8d"] = { "CHI OSA EVOCARE LOKHOLAR?", "." },
  ["7e47bdff6ae31741"] = { "Devi imparare da Zamja. Va' al Borstan's Firepit, al piano superiore di The Drag, prendendo le scale a sinistra quando entri dalla ⟦Valley of Strength=Valle della Forza⟧.", "." },
  ["7e4d3f30c695111d"] = { "Niente scalda le ossa come un po' di Celebrazione della Luna!", "." },
  ["7e50d7ad6632fcae"] = { "Tutte le raccolte sono finite, e le merci vengono spedite a ⟦Silithus=Silitus⟧ man mano che sono pronte. Pare che manchino meno di $2113w giorni perché arrivi tutto. Dopodiché basta trovare qualcuno che suoni quel gong e apra i cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧. E allora inizia il vero divertimento.", "." },
  ["7e5442699820262e"] = { "Che i giochi abbiano inizio!", "." },
  ["7e583f997a8f07a7"] = { "Qualcuno può dare una casa al mio adorabile gattino in più?", "." },
  ["7e6011ef27b57e5d"] = { "Sentite il potere dei ⟦Dark Iron Dwarves=Nani Ferroscuro⟧!", "." },
  ["7e680987ad9ca6ff"] = { "È un onore per me condividere il mio sapere con te, {name}. Fanne buon uso.", "." },
  ["7e6896cf0a36ec99"] = { "ETCIÙ!", "." },
  ["7e76540e70080d26"] = { "Loro mi consegnano i cadaveri, io li butto nella fossa.", "." },
  ["7e792e4aa9897e95"] = { "Dopotutto vali qualcosa. Lysta, evoca una sorpresa per le nostre giovani reclute.", "." },
  ["7e83949b9ba69e0b"] = { "Vieni, {name}! Andiamo laggiù a prenderlo!", "." },
  ["7e89858489b4476a"] = { "Il miglior minatore ha una presa salda sul piccone, un cuore forte nel petto e una spessa polvere nera tra i capelli.", "." },
  ["7e904f03cd6208b0"] = { "Usiamo l'arco da prima ancora dei tempi di mio padre. È solido e sicuro, e abbatte i nemici in fretta. Non vedo motivo di usare i fucili che piacciono tanto a goblin e tauren.", "." },
  ["7e91d9baa78aa26a"] = { "La tua volontà è forte, e il tuo intento è chiaro.\n\nForse ne sei <degno/degna>...", "." },
  ["7e922fd81ce5c670"] = { "Lascia questo posto, <straniero/straniera>, prima che ti consumi come ha consumato tutto ciò che ha toccato.", "." },
  ["7e9b1f33e5a4f1a4"] = { "Sì, sono il celebre mercante che con magnanimità ha sfamato gli, ehm, affamati... bambini...? ...di ⟦Undercity=Sepulcra⟧ durante la recente guerra contro il Flagello. Sì, sono il goblin d'affari visionario e il genio della logistica che da solo ha armato la resistenza e ha permesso alla nostra Dama Oscura di fondare la sua nazione di cadaveri puzzolenti... ehm, volevo dire, «Reietti».\n\nGià, sono io. Glix Xizzix. Sarei felice di firmarti un autografo. Per un piccolo compenso, naturalmente.\n\nChe ci faccio qui a gestire una barberia, chiedi? Beh, ho una parola per te, amico: diversificazione. Devi diversificare le tue fonti di guadagno!", "." },
  ["7ea5a820f8cf88de"] = { "Salute, <amico/amica> <mio/mia>. Che l'Alba ti protegga in questi tempi difficili.", "." },
  ["7ea5b785bafc0d9a"] = { "Lo sfidante è a terra!", "." },
  ["7ea94400b07477eb"] = { "Salve, amico! Sarei felice di offrirti un Tecnostruzzo, ma prima dovresti addestrarti con mio fratello Binjy, laggiù.\n\nSono molto più affidabili di qualsiasi bestia, ma possono essere difficili da pilotare per chi monta per la prima volta. Una volta che avrai imparato a pilotarne uno, però, non troverai compagno migliore!", "." },
  ["7eaecfed4c977bb7"] = { "I Calcaguerra sono pronti! Soldati dell'⟦Horde=Orda⟧, mi serve il vostro aiuto.", "." },
  ["7eb15444899377ee"] = { "Mi spiace, amico, qui a Brill non ne abbiamo. Per quello dovrai andare a ⟦Undercity=Sepulcra⟧. ⟦Undercity=Sepulcra⟧ si trova sotto le ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧, a sud di Brill. Dal retro delle rovine prendi l'ascensore per scendere, poi parla con uno degli Undercity Guardian per orientarti.", "." },
  ["7eb1967c6b258ef9"] = { "Non valevi l'energia spesa. <Nathanos sputa.>", "." },
  ["7eb686f56c59688a"] = { "Qui c'è un po' di spiffero... ma che m'importa? Tanto non sono più tra i vivi.", "." },
  ["7eb8b1d9235e82d9"] = { "Ho fallito... ho fallito nel mio dovere... ho tradito la mia gente... I worgen dilagano, e la Falce della mia dea è perduta.", "." },
  ["7ec773bb0d44365f"] = { "Riprova!", "." },
  ["7ecd9719fb2723b1"] = { "Il generale dei Lupi Bianchi è morto!", "." },
  ["7ecf3c2ceb7d70e5"] = { "La nostra attrazione più nuova, e senza alcun costo per te, aggiungerei: questi carri armati in miniatura, o Tonk, come li abbiamo astutamente chiamati, si possono comandare da una qualsiasi delle console di controllo dei Tonk sparse per la fiera.\n\nNon devi far altro che attivare una console libera. Ogni Tonk arriva con una dotazione standard di congegni e un potere speciale a caso da scatenare contro il nemico!\n\nCombatti battaglie epiche con i tuoi amici, vai in giro o semina un caos sfrenato... a te la scelta!", "." },
  ["7ed664c1668dd2b3"] = { "Mi assicuro che siamo riforniti e che le scarse risorse che abbiamo vengano distribuite come si deve.\n\nSe questo fosse un ordine vero e proprio, sarei una specie di intendente. Ma per come siamo messi, faccio solo del mio meglio perché siamo almeno in parte attrezzati per affrontare i pericoli che ci circondano.", "." },
  ["7ed8ead2c3580e8d"] = { "Ti prego, dimmi di più sugli ogre Gordunni.", "." },
  ["7edc4b7b1daf48d0"] = { "Ben <trovato/trovata>, {class}. Puoi parlare con me, a meno che tu non abbia affari diretti con la mia signora Magatha.\n\nMi occupo io della maggior parte delle sue faccende, così che lei possa concentrarsi su questioni più importanti. Forse c'è qualcosa di cui potremmo parlare, prima che tu chieda udienza a lei?", "." },
  ["7ee04716631d742f"] = { "Mmh, niente quassù.", "." },
  ["7ee055f998c7403b"] = { "Chi osa cercarmi?!", "." },
  ["7ee380ec3545855f"] = { "In groppa a una viverna si capisce che la sua fama di forza e velocità è ben meritata.", "." },
  ["7eef66a56f487164"] = { "Dimmi di più sul muisek.", "." },
})
